@extends('layouts.app') @section('title','Room Calendar') @section('page_title','Room Calendar') @section('content')<div class="page-head"><div><h1>14-day room calendar</h1><p>Quick visual occupancy and reservation plan from {{ $days->first()->format('d M') }}.</p></div><a class="btn primary" href="{{ route('reservations.create') }}">＋ New reservation</a></div><div class="card calendar-card"><div class="room-calendar"><div class="cal-row cal-head"><div class="cal-room">Room</div>@foreach($days as $d)<div class="cal-day"><b>{{ $d->format('D') }}</b><small>{{ $d->format('d M') }}</small></div>@endforeach</div>@foreach($rooms as $room)<div class="cal-row"><div class="cal-room"><b>{{ $room->room_number }}</b><small>{{ $room->roomType->name }}</small></div>@foreach($days as $d)@php $booking=$room->reservationRooms->first(fn($rr)=>$rr->check_in_at->startOfDay()->lte($d) && $rr->check_out_at->startOfDay()->gt($d) && !in_array($rr->reservation->status->value,['cancelled','checked_out'])); @endphp<div class="cal-day {{ $booking?'booked':'' }}">@if($booking)<a title="{{ $booking->reservation->guest->full_name }}" href="{{ route('reservations.show',$booking->reservation) }}">{{ Str::limit($booking->reservation->guest->first_name,7) }}</a>@else<span>·</span>@endif</div>@endforeach</div>@endforeach</div></div>@endsection
